function v100Esc(v){return escapeHtml(String(v??''));}
function v100Date(v){if(!v)return 'Sin fecha';try{return new Date(v).toLocaleDateString('es-AR');}catch(_){return String(v)}}
function v100Money(v,c='ARS'){try{return new Intl.NumberFormat('es-AR',{style:'currency',currency:c||'ARS',maximumFractionDigits:0}).format(Number(v||0));}catch(_){return `${Number(v||0).toLocaleString('es-AR')} ${c||''}`}}
function v100Priority(p){return ({critica:['Crítica','bg-red-100 text-red-700'],alta:['Alta','bg-orange-100 text-orange-700'],media:['Media','bg-amber-50 text-amber-700'],baja:['Baja','bg-slate-100 text-slate-600']})[p]||[p||'Media','bg-slate-100 text-slate-600'];}
function v100Initials(name){return String(name||'LU').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();}

