const V100_STOP=new Set('de la el los las un una y e o u en para por con sin del al se su sus que como es son ser esta este esto esa ese ya muy mas más a ante bajo cabe contra desde durante entre hacia hasta mediante según segun sobre tras versus via puesto trabajo empresa persona experiencia requisito requisitos excluyente deseable buscamos búsqueda busqueda'.split(/\s+/));
const V100_CANON={
  electrico:'electricidad',electrica:'electricidad',eléctrico:'electricidad',eléctrica:'electricidad',electricidad:'electricidad',tablero:'electricidad',tableros:'electricidad',cableado:'electricidad',tension:'electricidad',tensión:'electricidad',
  refrigeracion:'refrigeracion',refrigeración:'refrigeracion',climatizacion:'refrigeracion',climatización:'refrigeracion',hvac:'refrigeracion',split:'refrigeracion',
  mantenimiento:'mantenimiento',mantenimientos:'mantenimiento',preventivo:'mantenimiento',correctivo:'mantenimiento',edilicio:'mantenimiento',
  supervisor:'supervision',supervisión:'supervision',supervision:'supervision',lider:'liderazgo',líder:'liderazgo',liderazgo:'liderazgo',coordinacion:'coordinacion',coordinación:'coordinacion',coordinador:'coordinacion',
  rrhh:'rrhh','recursos humanos':'rrhh',seleccion:'seleccion',selección:'seleccion',reclutamiento:'seleccion',
  calidad:'calidad',iso9001:'calidad','iso 9001':'calidad',procesos:'procesos',proceso:'procesos',
  plomeria:'sanitaria',plomería:'sanitaria',sanitario:'sanitaria',sanitaria:'sanitaria',fontaneria:'sanitaria',fontanería:'sanitaria',
  durlock:'durlock',yeso:'durlock',albanileria:'albanileria',albañilería:'albanileria',albañil:'albanileria',
  excel:'excel',office:'office',administrativo:'administracion',administrativa:'administracion',administración:'administracion',administracion:'administracion',
  seguridad:'seguridad',higiene:'seguridad',epp:'seguridad',
  ventas:'ventas',vendedor:'ventas',comercial:'ventas',atencion:'atencion',atención:'atencion',cliente:'atencion'
};
function v100Norm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9+#. ]+/g,' ').replace(/\s+/g,' ').trim();}
function v100Tokens(s){return v100Norm(s).split(' ').filter(x=>x.length>2&&!V100_STOP.has(x)).map(x=>V100_CANON[x]||x);}
function v100Vector(parts){const m=new Map();for(const [text,w] of parts){for(const t of v100Tokens(text))m.set(t,(m.get(t)||0)+Number(w||1));}return m;}
function v100OverlapScore(target,evidence){let total=0,hit=0;for(const [t,w] of target){total+=w;if(evidence.has(t))hit+=w;}return total?Math.round(hit*100/total):0;}
function v100EvidenceTokens(){
  const p=talentData?.profile||{};
  const parts=[[p.headline,3],[p.bio,1],[p.desired_role,2]];
  (talentData?.skills||[]).forEach(s=>parts.push([s.skill,3+Number(s.level||3)/2]));
  (talentData?.experiences||[]).forEach(e=>{parts.push([e.position_title,3]);parts.push([e.description,1.3]);parts.push([e.company_name,.3]);});
  (talentData?.certificates||[]).forEach(c=>parts.push([c.course_title,3]));
  return v100Vector(parts);
}
function v100Relevance(text,target){const toks=new Set(v100Tokens(text));let s=0;for(const [t,w] of target)if(toks.has(t))s+=w;return s;}
function buildAgentAnalysisV100(job){
  if(!job)return null;
  const target=v100Vector([[job.title,5],[job.requirements,3.5],[job.description,1.4],[job.location,.3],[job.modality,.3]]),evidence=v100EvidenceTokens();
  const entries=[...target.entries()].sort((a,b)=>b[1]-a[1]);
  const matched=entries.filter(([t])=>evidence.has(t)).slice(0,12).map(([t])=>t);
  const missing=entries.filter(([t])=>!evidence.has(t)).slice(0,8).map(([t])=>t);
  let score=v100OverlapScore(target,evidence);
  const p=talentData?.profile||{};
  if(job.location&&p.desired_location&&v100Norm(job.location).includes(v100Norm(p.desired_location)))score=Math.min(100,score+3);
  if(job.modality&&p.desired_modality&&p.desired_modality!=='indistinto'&&v100Norm(job.modality)===v100Norm(p.desired_modality))score=Math.min(100,score+2);
  const skills=[...(talentData?.skills||[])].map(x=>({...x,_r:v100Relevance(x.skill,target)})).sort((a,b)=>b._r-a._r||Number(b.level||0)-Number(a.level||0));
  const experiences=[...(talentData?.experiences||[])].map(x=>({...x,_r:v100Relevance(`${x.position_title} ${x.description||''}`,target)})).sort((a,b)=>b._r-a._r||new Date(b.start_date||0)-new Date(a.start_date||0));
  const certs=[...(talentData?.certificates||[])].map(x=>({...x,_r:v100Relevance(x.course_title,target)})).sort((a,b)=>b._r-a._r||new Date(b.issued_at||0)-new Date(a.issued_at||0));
  const relatedCourses=(publicCatalog||[]).map(c=>({...c,_r:v100Relevance(`${c.title} ${c.description||''}`,new Map(missing.map(x=>[x,1])))})).filter(c=>c._r>0).sort((a,b)=>b._r-a._r).slice(0,4);
  const topSkills=skills.filter(x=>x._r>0).slice(0,6);
  const questions=[
    `Contá una situación concreta en la que aplicaste ${matched[0]||'una competencia relevante para el puesto'}.`,
    `¿Qué experiencia tuya se relaciona mejor con el rol de ${job.title}?`,
    missing[0]?`La búsqueda menciona ${missing[0]}. ¿Qué experiencia real tenés con ese tema y qué te faltaría aprender?`:`¿Qué parte del puesto requeriría mayor aprendizaje al incorporarte?`,
    `Describí un problema laboral que hayas resuelto y cómo verificaste el resultado.`,
    `¿Qué evidencia concreta (curso, certificado, proyecto o experiencia) respalda mejor tu postulación?`
  ];
  return {job,score,matched,missing,skills,experiences,certs,relatedCourses,questions,generatedAt:new Date().toISOString()};
}
function v100AgentScoreUi(score){const cls=score>=70?'bg-emerald-50 text-emerald-700 border-emerald-100':score>=45?'bg-blue-50 text-blue-700 border-blue-100':'bg-amber-50 text-amber-700 border-amber-100';return `<div class="rounded-2xl border ${cls} p-4"><p class="text-[10px] uppercase font-black">Afinidad documental orientativa</p><p class="mt-1 text-3xl font-black">${score}%</p><p class="mt-1 text-[10px] opacity-80">Se basa sólo en lo cargado en tu perfil. No decide ni predice una contratación.</p></div>`;}
function v100AgentSummaryHtml(a){if(!a)return '<p class="text-sm text-slate-500">Elegí una búsqueda.</p>';return `<div class="grid md:grid-cols-[180px_1fr] gap-4">${v100AgentScoreUi(a.score)}<div class="rounded-2xl bg-white border border-slate-100 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Evidencia encontrada</p><div class="mt-2 flex flex-wrap gap-1.5">${a.matched.length?a.matched.map(x=>`<span class="px-2 py-1 rounded-lg bg-emerald-50 text-emerald-700 text-[10px] font-bold">${v100Esc(x)}</span>`).join(''):'<span class="text-xs text-slate-400">Todavía no detecté coincidencias claras.</span>'}</div><p class="mt-4 text-[10px] uppercase font-bold text-slate-400">Temas de la búsqueda sin evidencia clara en tu perfil</p><div class="mt-2 flex flex-wrap gap-1.5">${a.missing.length?a.missing.map(x=>`<span class="px-2 py-1 rounded-lg bg-amber-50 text-amber-700 text-[10px] font-bold">${v100Esc(x)}</span>`).join(''):'<span class="text-xs text-emerald-700 font-bold">No detecté brechas textuales relevantes.</span>'}</div></div></div>`;}
