function agentAnswerTextV100(kind,a){if(!a)return 'Elegí una búsqueda primero.';if(kind==='gap')return a.missing.length?`En tu perfil no encontré evidencia clara para: ${a.missing.join(', ')}. Esto no significa que no lo sepas: puede ser que todavía no esté cargado. Antes de postularte, completá el perfil sólo con experiencia real.`:'No detecté brechas textuales importantes con la información cargada.';if(kind==='interview')return `Preguntas para practicar:\n• ${a.questions.join('\n• ')}`;if(kind==='course')return a.relatedCourses.length?`Cursos de Lutmin que se relacionan con temas faltantes: ${a.relatedCourses.map(c=>c.title).join(', ')}.`:'No encontré un curso publicado que cubra de forma directa los temas faltantes.';return `Para ${a.job.title}, conviene priorizar: ${a.matched.slice(0,6).join(', ')||'tu experiencia más cercana al puesto'}. El CV adaptado reordena competencias, experiencia y certificados por relevancia, pero no agrega datos que no existan en tu perfil.`;}
