async function confirmSmartApplyV100(){const p=pendingSmartApplicationV100;if(!p)return;const msg=document.getElementById('smartApplyMessageV100')?.value.trim()||null;const {data,error}=await supabaseClient.from('job_applications').insert({job_id:p.job.id,user_id:currentLutminUser.id,message:msg}).select('id').single();if(error)return showToast(error.code==='23505'?'Ya estás postulado/a a esta búsqueda.':error.message||'No pude registrar la postulación.');const save=await supabaseClient.rpc('save_application_cv_snapshot_v100',{p_application_id:data.id,p_job_id:p.job.id,p_affinity:p.analysis.score,p_matching_terms:p.analysis.matched,p_gap_terms:p.analysis.missing,p_snapshot:p.snapshot});if(save.error)console.error('Snapshot CV V10',save.error);hideV100Modal('smartApplyModalV100');pendingSmartApplicationV100=null;showToast('Postulación enviada con CV dinámico asociado.');await loadTalentCenter();}
const _applyTalentJobV100=typeof applyTalentJob==='function'?applyTalentJob:null;
if(_applyTalentJobV100)applyTalentJob=function(jobId){return openSmartApplyV100(jobId);};

async function loadTalentSnapshotsV100(){if(currentLutminUser?.role!=='student')return;const {data,error}=await supabaseClient.rpc('my_application_cv_snapshots_v100');talentSnapshotsV100=error?[]:(Array.isArray(data)?data:[]);}
function enhanceTalentApplicationsV100(){const root=document.getElementById('talentApplicationsList');if(!root)return;const apps=talentData?.applications||[];[...root.children].forEach((el,i)=>{const app=apps[i];if(!app)return;const s=talentSnapshotsV100.find(x=>x.application_id===app.id);if(!s||el.querySelector('[data-v100-snapshot]'))return;const btn=document.createElement('button');btn.dataset.v100Snapshot='1';btn.className='mt-3 ml-2 text-[11px] text-blue-700 font-bold';btn.innerHTML='<i class="fa-solid fa-file-lines mr-1"></i>CV dinámico enviado';btn.onclick=()=>showOwnSnapshotV100(s);el.appendChild(btn);});}
function showOwnSnapshotV100(s){const m=ensureV100Modal('ownSnapshotModalV100','max-w-3xl'),b=m.querySelector('[data-v100-body]'),snap=s.snapshot||{};b.innerHTML=`<p class="text-[10px] uppercase font-black tracking-widest text-lutmin-light">Snapshot de postulación</p><h2 class="mt-2 text-2xl font-black text-lutmin-dark">${v100Esc(snap.job?.title||'CV dinámico')}</h2><p class="mt-1 text-xs text-slate-500">Guardado el ${v100Date(s.generated_at)} · versión ${v100Esc(s.algorithm_version)}</p><div class="mt-5">${v100SnapshotBodyHtml(snap)}</div>`;showV100Modal('ownSnapshotModalV100');}
function v100SnapshotBodyHtml(snap){return `<div class="rounded-2xl bg-slate-50 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Perfil presentado</p><p class="mt-1 font-extrabold text-lutmin-dark">${v100Esc(snap.profile?.headline||'Perfil profesional')}</p><div class="mt-3 flex flex-wrap gap-1.5">${(snap.focus_terms||[]).map(x=>`<span class="px-2 py-1 rounded-lg bg-blue-50 text-blue-700 text-[10px] font-bold">${v100Esc(x)}</span>`).join('')}</div></div><div class="mt-4 grid lg:grid-cols-2 gap-4"><div><h3 class="font-extrabold text-lutmin-dark">Competencias priorizadas</h3><div class="mt-2 space-y-2">${(snap.skills||[]).slice(0,8).map(s=>`<div class="rounded-xl border border-slate-100 p-3 text-xs"><strong>${v100Esc(s.skill)}</strong> · ${Number(s.level||0)}/5</div>`).join('')||'<p class="text-xs text-slate-400">Sin datos.</p>'}</div></div><div><h3 class="font-extrabold text-lutmin-dark">Experiencia priorizada</h3><div class="mt-2 space-y-2">${(snap.experiences||[]).slice(0,5).map(x=>`<div class="rounded-xl border border-slate-100 p-3"><p class="text-xs font-bold">${v100Esc(x.position_title)} · ${v100Esc(x.company_name)}</p><p class="mt-1 text-[10px] text-slate-500">${v100Esc(x.description||'')}</p></div>`).join('')||'<p class="text-xs text-slate-400">Sin datos.</p>'}</div></div></div>`;}

const _openCompanyCandidateProfileV100=typeof openCompanyCandidateProfile==='function'?openCompanyCandidateProfile:null;
if(_openCompanyCandidateProfileV100)openCompanyCandidateProfile=async function(userId,applicationId=null){const r=await _openCompanyCandidateProfileV100.apply(this,arguments);if(applicationId)await injectCompanyDynamicCvV100(applicationId);return r;};
async function injectCompanyDynamicCvV100(applicationId){const root=document.getElementById('companyCandidateContent');if(!root||root.querySelector('[data-v100-company-cv]'))return;const {data,error}=await supabaseClient.rpc('company_application_cv_snapshot_v100',{p_application_id:applicationId});if(error||!data?.snapshot)return;const card=document.createElement('div');card.dataset.v100CompanyCv='1';card.className='mt-5 rounded-2xl border border-cyan-100 bg-cyan-50/60 p-4';card.innerHTML=`<div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3"><div><p class="text-[10px] uppercase font-black text-cyan-700">CV dinámico enviado por el candidato</p><p class="mt-1 text-sm font-extrabold text-lutmin-dark">Versión adaptada a esta búsqueda</p><p class="mt-1 text-[10px] text-slate-500">Sólo reorganiza información declarada/validada del perfil. No es un ranking ni una recomendación de contratación.</p></div><button class="px-3 py-2 rounded-xl bg-white text-cyan-800 border border-cyan-100 text-xs font-bold">Ver contenido</button></div>`;card.querySelector('button').onclick=()=>{const m=ensureV100Modal('companySnapshotModalV100','max-w-3xl');m.querySelector('[data-v100-body]').innerHTML=`<p class="text-[10px] uppercase font-black tracking-widest text-cyan-700">CV de la postulación</p><h2 class="mt-2 text-2xl font-black text-lutmin-dark">${v100Esc(data.snapshot.job?.title||'Postulación')}</h2><div class="mt-5">${v100SnapshotBodyHtml(data.snapshot)}</div>`;showV100Modal('companySnapshotModalV100')};root.firstElementChild?.insertAdjacentElement('afterend',card);}

