function ensureAdminDevelopmentNavV100(){
  if(typeof ADMIN_MODULES_V19!=='undefined')ADMIN_MODULES_V19.development={title:'Desarrollo',description:'Puestos, brechas, plan anual, necesidades, desarrollo individual y automatizaciones.'};
  const select=document.getElementById('adminModuleSelectV20');if(select&&!select.querySelector('option[value="development"]')){const o=document.createElement('option');o.value='development';o.textContent='Desarrollo y automatización';select.insertBefore(o,select.querySelector('option[value="system"]'))}
  const nav=document.querySelector('[data-admin-v19-btn="system"]')?.parentElement;if(nav&&!nav.querySelector('[data-admin-v19-btn="development"]')){const btn=document.createElement('button');btn.dataset.adminV19Btn='development';btn.className='admin-v19-nav px-3 py-2.5 rounded-xl text-xs font-bold bg-white text-slate-600';btn.innerHTML='<i class="fa-solid fa-chart-network mr-2"></i>Desarrollo <span id="adminBadgeDevelopmentV100" class="ml-1"></span>';btn.onclick=()=>setAdminModuleV19('development');nav.insertBefore(btn,nav.querySelector('[data-admin-v19-btn="system"]'));}
}
function ensureAdminDevelopmentPanelV100(){const admin=document.querySelector('section[data-campus-panel="admin"]');if(!admin||document.getElementById('adminDevelopmentV100'))return;const wrap=document.createElement('div');wrap.id='adminDevelopmentV100';wrap.dataset.adminModuleV19='development';wrap.className='mt-6';wrap.innerHTML=`<div class="rounded-3xl bg-white border border-slate-100 p-5 sm:p-6"><div class="flex flex-col xl:flex-row xl:items-end xl:justify-between gap-4"><div><p class="text-[10px] uppercase tracking-widest font-black text-lutmin-light">Gestión integral</p><h3 class="mt-1 text-2xl font-black text-lutmin-dark">Desarrollo y automatización</h3><p class="mt-2 text-sm text-slate-500">Perfiles de puesto, brechas, necesidades, plan anual y centro de acciones.</p></div><div class="flex gap-2 items-end"><div><label class="text-[10px] uppercase font-bold text-slate-400">Empresa</label><select id="adminDevCompanyV100" onchange="selectAdminDevCompanyV100(this.value)" class="mt-1 px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-sm min-w-[230px]"></select></div><button onclick="loadAdminDevelopmentV100()" class="px-4 py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Actualizar</button></div></div><div id="adminDevBodyV100" class="mt-6"><div class="text-sm text-slate-500">Elegí una empresa.</div></div></div>`;admin.appendChild(wrap);}
function ensureCompanyDevelopmentPanelV100(){const panel=document.querySelector('section[data-campus-panel="company"]');if(!panel||document.getElementById('companyDevelopmentV100'))return;const wrap=document.createElement('div');wrap.id='companyDevelopmentV100';wrap.className='mt-6 rounded-[2rem] border border-blue-100 bg-gradient-to-br from-blue-50/70 to-white p-5 sm:p-6';wrap.innerHTML=`<div class="flex flex-col xl:flex-row xl:items-center xl:justify-between gap-4"><div><p class="text-[10px] uppercase tracking-widest font-black text-lutmin-light">Gestión de talento</p><h3 class="mt-1 text-2xl font-black text-lutmin-dark">Planificación y brechas del equipo</h3><p class="mt-1 text-sm text-slate-500">De la necesidad a la capacitación, competencia y seguimiento.</p></div><button onclick="loadCompanyDevelopmentV100()" class="px-4 py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Actualizar motor</button></div><div id="companyDevBodyV100" class="mt-5"><div class="text-sm text-slate-500">Cargando...</div></div>`;const firstStats=panel.querySelector('.mt-6.grid');firstStats?.insertAdjacentElement('afterend',wrap);}
function devContextV100(mode){return mode==='admin'?adminDevV100:companyDevV100;}
function devCompanyArgV100(mode){return mode==='admin'?(adminDevV100.companyId||null):null;}
async function fetchDevelopmentV100(mode){const p=devCompanyArgV100(mode);const [d,g]=await Promise.all([supabaseClient.rpc('development_center_v100',{p_company_id:p}),supabaseClient.rpc('gap_matrix_v100',{p_company_id:p})]);if(d.error)throw d.error;return {data:d.data||{},gaps:Array.isArray(g.data)?g.data:[]};}
async function loadCompanyDevelopmentV100(){if(currentLutminUser?.role!=='company_admin')return;ensureCompanyDevelopmentPanelV100();try{await supabaseClient.rpc('refresh_company_automation_v100',{p_company_id:null});const r=await fetchDevelopmentV100('company');companyDevV100.data=r.data;companyDevV100.gaps=r.gaps;renderDevelopmentV100('company');}catch(e){console.error(e);document.getElementById('companyDevBodyV100').innerHTML='<div class="rounded-2xl bg-amber-50 border border-amber-100 p-4 text-sm text-amber-800">Este módulo todavía no está habilitado. Contactá a Administración.</div>';}}
async function loadAdminDevelopmentV100(){if(currentLutminUser?.role!=='admin')return;ensureAdminDevelopmentNavV100();ensureAdminDevelopmentPanelV100();const sel=document.getElementById('adminDevCompanyV100');if(sel){const prev=adminDevV100.companyId||sel.value;sel.innerHTML='<option value="">Elegí una empresa</option>'+(adminCompanies||[]).map(c=>`<option value="${c.id}">${v100Esc(c.name)}</option>`).join('');if(prev&&[...sel.options].some(o=>o.value===prev)){sel.value=prev;adminDevV100.companyId=prev;}}if(!adminDevV100.companyId)return;try{await supabaseClient.rpc('refresh_company_automation_v100',{p_company_id:adminDevV100.companyId});const r=await fetchDevelopmentV100('admin');adminDevV100.data=r.data;adminDevV100.gaps=r.gaps;renderDevelopmentV100('admin');}catch(e){console.error(e);document.getElementById('adminDevBodyV100').innerHTML='<div class="rounded-2xl bg-amber-50 border border-amber-100 p-4 text-sm text-amber-800">No pude cargar V10. Verificá que el SQL esté ejecutado.</div>';}}
function selectAdminDevCompanyV100(id){adminDevV100.companyId=id||null;if(id)loadAdminDevelopmentV100();else document.getElementById('adminDevBodyV100').innerHTML='<div class="text-sm text-slate-500">Elegí una empresa.</div>';}
function setDevTabV100(mode,tab){devContextV100(mode).tab=tab;renderDevelopmentV100(mode);}
function devTabButtonV100(mode,key,label,icon){const active=devContextV100(mode).tab===key;return `<button onclick="setDevTabV100('${mode}','${key}')" class="px-3 py-2.5 rounded-xl text-xs font-bold ${active?'bg-lutmin-dark text-white':'bg-white border border-slate-100 text-slate-600'}"><i class="fa-solid ${icon} mr-1"></i>${label}</button>`;}
function renderDevelopmentV100(mode){const ctx=devContextV100(mode),d=ctx.data||{},g=ctx.gaps||[],root=document.getElementById(mode==='admin'?'adminDevBodyV100':'companyDevBodyV100');if(!root)return;const actions=d.actions||[],needs=d.needs||[],plans=d.plans||[],profiles=d.role_profiles||[],assigned=g.filter(x=>x.role_profile_id),avg=assigned.length?Math.round(assigned.reduce((n,x)=>n+Number(x.compliance_percent||0),0)/assigned.length):100;root.innerHTML=`<div class="grid grid-cols-2 xl:grid-cols-5 gap-3"><div class="rounded-2xl bg-white border border-slate-100 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Perfiles de puesto</p><p class="mt-1 text-2xl font-black text-lutmin-dark">${profiles.length}</p></div><div class="rounded-2xl bg-white border border-slate-100 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Cumplimiento promedio</p><p class="mt-1 text-2xl font-black text-blue-600">${avg}%</p></div><div class="rounded-2xl bg-white border border-slate-100 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Brechas abiertas</p><p class="mt-1 text-2xl font-black text-amber-600">${g.reduce((n,x)=>n+(x.gaps||[]).length,0)}</p></div><div class="rounded-2xl bg-white border border-slate-100 p-4"><p class="text-[10px] uppercase font-bold text-slate-400">Necesidades</p><p class="mt-1 text-2xl font-black text-violet-600">${needs.filter(x=>!['resolved','cancelled'].includes(x.status)).length}</p></div><div class="rounded-2xl bg-white border border-slate-100 p-4 col-span-2 xl:col-span-1"><p class="text-[10px] uppercase font-bold text-slate-400">Acciones automáticas</p><p class="mt-1 text-2xl font-black text-red-600">${actions.length}</p></div></div><div class="mt-4 flex flex-wrap gap-2">${devTabButtonV100(mode,'overview','Acciones','fa-bolt')}${devTabButtonV100(mode,'roles','Puestos y brechas','fa-people-arrows-left-right')}${devTabButtonV100(mode,'needs','Necesidades','fa-triangle-exclamation')}${devTabButtonV100(mode,'plan','Plan anual','fa-calendar-check')}${devTabButtonV100(mode,'individual','Desarrollo individual','fa-user-graduate')}${devTabButtonV100(mode,'automation','Automatizaciones','fa-gears')}</div><div id="devTabBodyV100_${mode}" class="mt-4"></div>`;renderDevTabBodyV100(mode);}
function renderDevTabBodyV100(mode){const ctx=devContextV100(mode),d=ctx.data||{},root=document.getElementById(`devTabBodyV100_${mode}`);if(!root)return;if(ctx.tab==='roles')return renderDevRolesV100(mode,root,d);if(ctx.tab==='needs')return renderDevNeedsV100(mode,root,d);if(ctx.tab==='plan')return renderDevPlanV100(mode,root,d);if(ctx.tab==='individual')return renderDevIndividualV100(mode,root,d);if(ctx.tab==='automation')return renderDevAutomationV100(mode,root,d);renderDevActionsV100(mode,root,d);}
function memberNameV100(d,id){const p=(d.members||[]).find(x=>x.user_id===id);return p?.full_name||p?.email||'Persona';}
function renderDevActionsV100(mode,root,d){const actions=d.actions||[];root.innerHTML=`<div class="grid xl:grid-cols-[1.15fr_.85fr] gap-4"><div class="rounded-3xl bg-white border border-slate-100 overflow-hidden"><div class="p-5 border-b border-slate-100"><h4 class="font-extrabold text-lutmin-dark">Centro de acciones automáticas</h4><p class="mt-1 text-xs text-slate-500">Se generan por cambios reales en competencias, cursos, vencimientos y planes. No dependen de revisar manualmente toda la base.</p></div><div class="divide-y divide-slate-100">${actions.length?actions.slice(0,30).map(a=>{const pr=v100Priority(a.priority);return `<div class="p-4 flex flex-col lg:flex-row lg:items-center lg:justify-between gap-3"><div><div class="flex flex-wrap gap-2"><span class="px-2 py-1 rounded-lg text-[9px] font-bold ${pr[1]}">${pr[0]}</span><span class="px-2 py-1 rounded-lg bg-slate-100 text-slate-600 text-[9px] font-bold">${v100Esc(a.category)}</span></div><p class="mt-2 text-sm font-extrabold text-lutmin-dark">${v100Esc(a.title)}</p><p class="mt-1 text-xs text-slate-500">${a.user_id?v100Esc(memberNameV100(d,a.user_id))+' · ':''}${v100Esc(a.description||'')}${a.due_at?' · objetivo '+v100Date(a.due_at):''}</p></div><button onclick="closeDevActionV100('${mode}','${a.id}')" class="px-3 py-2 rounded-xl bg-emerald-50 text-emerald-700 text-xs font-bold">Marcar resuelta</button></div>`}).join(''):'<div class="p-8 text-center text-sm text-slate-500">No hay acciones pendientes.</div>'}</div></div><div class="rounded-3xl bg-lutmin-dark text-white p-5"><p class="text-[10px] uppercase font-black tracking-widest text-blue-200">Cómo funciona</p><h4 class="mt-2 text-xl font-black">Automatización sin costo por ejecución</h4><div class="mt-4 space-y-3 text-xs text-slate-300"><p><i class="fa-solid fa-check text-lutmin-light mr-2"></i>Cambio de competencia → recalcula brecha.</p><p><i class="fa-solid fa-check text-lutmin-light mr-2"></i>Curso completado → recalcula requisitos.</p><p><i class="fa-solid fa-check text-lutmin-light mr-2"></i>Certificado con vencimiento → agenda renovación.</p><p><i class="fa-solid fa-check text-lutmin-light mr-2"></i>Hito de plan → crea seguimiento.</p><p><i class="fa-solid fa-check text-lutmin-light mr-2"></i>Todo queda dentro de Supabase y del navegador.</p></div></div></div>`;}
async function closeDevActionV100(mode,id){const {error}=await supabaseClient.rpc('set_action_status_v100',{p_company_id:devCompanyArgV100(mode),p_action_id:id,p_status:'done'});if(error)return showToast(error.message||'No pude cerrar la acción.');showToast('Acción resuelta.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
function renderDevRolesV100(mode,root,d){const profiles=d.role_profiles||[],comps=d.role_competencies||[],courses=d.role_courses||[],assign=d.assignments||[],gaps=devContextV100(mode).gaps||[];root.innerHTML=`<div class="grid xl:grid-cols-[.8fr_1.2fr] gap-4"><div class="space-y-4"><form onsubmit="saveRoleProfileV100(event,'${mode}')" class="rounded-3xl bg-white border border-slate-100 p-5"><h4 class="font-extrabold text-lutmin-dark">Nuevo perfil de puesto</h4><input name="name" required class="mt-3 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-sm" placeholder="Ej: Técnico de mantenimiento"><input name="area" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-sm" placeholder="Área / sector"><textarea name="description" rows="2" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-sm" placeholder="Objetivo del puesto"></textarea><button class="mt-3 w-full py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Crear perfil</button></form><div class="rounded-3xl bg-white border border-slate-100 p-5"><h4 class="font-extrabold text-lutmin-dark">Asignar puesto</h4><div class="mt-3 grid gap-2"><select id="devAssignMember_${mode}" class="px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs">${(d.members||[]).map(m=>`<option value="${m.user_id}">${v100Esc(m.full_name||m.email)}</option>`).join('')}</select><select id="devAssignRole_${mode}" class="px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs">${profiles.map(r=>`<option value="${r.id}">${v100Esc(r.name)}</option>`).join('')}</select><button onclick="assignDevRoleV100('${mode}')" class="py-2.5 rounded-xl bg-blue-600 text-white text-xs font-bold">Asignar y recalcular brecha</button></div></div></div><div class="space-y-4">${profiles.length?profiles.map(r=>`<div class="rounded-3xl bg-white border border-slate-100 p-5"><div class="flex justify-between gap-3"><div><p class="text-[10px] uppercase font-bold text-slate-400">${v100Esc(r.area||'Perfil de puesto')}</p><h4 class="mt-1 text-lg font-black text-lutmin-dark">${v100Esc(r.name)}</h4><p class="mt-1 text-xs text-slate-500">${v100Esc(r.description||'Sin descripción')}</p></div><span class="text-[10px] px-2 py-1 rounded-full bg-blue-50 text-blue-700 font-bold h-fit">${assign.filter(a=>a.role_profile_id===r.id).length} personas</span></div><div class="mt-4 grid lg:grid-cols-2 gap-3"><form onsubmit="addRoleCompV100(event,'${mode}','${r.id}')" class="rounded-2xl bg-slate-50 p-3"><p class="text-xs font-bold text-lutmin-dark">Agregar competencia requerida</p><select name="comp" class="mt-2 w-full px-2 py-2 rounded-xl bg-white border border-slate-200 text-xs">${(d.competencies||[]).map(c=>`<option value="${c.id}">${v100Esc(c.name)}</option>`).join('')}</select><div class="mt-2 grid grid-cols-[90px_1fr] gap-2"><select name="level" class="px-2 py-2 rounded-xl bg-white border border-slate-200 text-xs">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===3?'selected':''}>${n}/5</option>`).join('')}</select><label class="flex items-center gap-2 px-2 text-[10px] font-bold"><input name="validation" type="checkbox"> Validación requerida</label></div><button class="mt-2 w-full py-2 rounded-xl bg-blue-600 text-white text-[10px] font-bold">Agregar</button></form><form onsubmit="addRoleCourseV100(event,'${mode}','${r.id}')" class="rounded-2xl bg-slate-50 p-3"><p class="text-xs font-bold text-lutmin-dark">Agregar curso obligatorio</p><select name="course" class="mt-2 w-full px-2 py-2 rounded-xl bg-white border border-slate-200 text-xs">${(d.courses||[]).map(c=>`<option value="${c.id}">${v100Esc(c.title)}</option>`).join('')}</select><label class="mt-2 flex items-center gap-2 text-[10px] font-bold"><input name="certificate" type="checkbox"> Exigir certificado vigente</label><button class="mt-2 w-full py-2 rounded-xl bg-violet-600 text-white text-[10px] font-bold">Agregar</button></form></div><div class="mt-4 flex flex-wrap gap-2">${comps.filter(x=>x.role_profile_id===r.id).map(x=>`<span class="px-2.5 py-1.5 rounded-xl bg-blue-50 text-blue-700 text-[10px] font-bold">${v100Esc(x.competency_name)} · ${x.required_level}/5${x.require_validation?' · validada':''}</span>`).join('')}${courses.filter(x=>x.role_profile_id===r.id).map(x=>`<span class="px-2.5 py-1.5 rounded-xl bg-violet-50 text-violet-700 text-[10px] font-bold">${v100Esc(x.course_title)}${x.require_valid_certificate?' · cert. vigente':''}</span>`).join('')}</div></div>`).join(''):'<div class="rounded-3xl bg-white border border-slate-100 p-8 text-center text-sm text-slate-500">Creá el primer perfil de puesto.</div>'}<div class="rounded-3xl bg-white border border-slate-100 overflow-hidden"><div class="p-5 border-b border-slate-100"><h4 class="font-extrabold text-lutmin-dark">Matriz persona vs. puesto</h4></div><div class="overflow-x-auto"><table class="min-w-full text-xs"><thead class="bg-slate-50"><tr><th class="text-left p-3">Persona</th><th class="text-left p-3">Puesto</th><th class="text-left p-3">Cumplimiento</th><th class="text-left p-3">Brechas</th></tr></thead><tbody>${gaps.map(x=>`<tr class="border-t border-slate-100"><td class="p-3 font-bold text-lutmin-dark">${v100Esc(x.full_name)}</td><td class="p-3">${v100Esc(x.role_name||'Sin perfil asignado')}</td><td class="p-3"><span class="font-black ${Number(x.compliance_percent||0)>=80?'text-emerald-600':Number(x.compliance_percent||0)>=50?'text-amber-600':'text-red-600'}">${Number(x.compliance_percent||0)}%</span></td><td class="p-3">${(x.gaps||[]).slice(0,4).map(g=>v100Esc(g.name)).join(' · ')||'—'}</td></tr>`).join('')}</tbody></table></div></div></div></div>`;}
async function saveRoleProfileV100(e,mode){e.preventDefault();const f=new FormData(e.target);const {error}=await supabaseClient.rpc('save_role_profile_v100',{p_company_id:devCompanyArgV100(mode),p_id:null,p_name:f.get('name'),p_description:f.get('description')||null,p_area:f.get('area')||null,p_active:true});if(error)return showToast(error.message||'No pude crear el perfil.');e.target.reset();showToast('Perfil de puesto creado.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
async function addRoleCompV100(e,mode,role){e.preventDefault();const f=new FormData(e.target);const {error}=await supabaseClient.rpc('save_role_competency_v100',{p_company_id:devCompanyArgV100(mode),p_role_profile_id:role,p_competency_id:f.get('comp'),p_required_level:Number(f.get('level')||3),p_require_validation:f.get('validation')==='on',p_mandatory:true});if(error)return showToast(error.message||'No pude agregar el requisito.');showToast('Competencia requerida agregada.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
async function addRoleCourseV100(e,mode,role){e.preventDefault();const f=new FormData(e.target);const {error}=await supabaseClient.rpc('save_role_course_v100',{p_company_id:devCompanyArgV100(mode),p_role_profile_id:role,p_course_id:f.get('course'),p_mandatory:true,p_require_valid_certificate:f.get('certificate')==='on',p_recurrence_months:null});if(error)return showToast(error.message||'No pude agregar el curso.');showToast('Curso requerido agregado.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
async function assignDevRoleV100(mode){const user=document.getElementById(`devAssignMember_${mode}`)?.value,role=document.getElementById(`devAssignRole_${mode}`)?.value;if(!user||!role)return showToast('Elegí persona y perfil.');const {error}=await supabaseClient.rpc('assign_role_profile_v100',{p_company_id:devCompanyArgV100(mode),p_user_id:user,p_role_profile_id:role});if(error)return showToast(error.message||'No pude asignar el puesto.');showToast('Puesto asignado y brechas recalculadas.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
function renderDevNeedsV100(mode,root,d){root.innerHTML=`<div class="grid xl:grid-cols-[.75fr_1.25fr] gap-4"><form onsubmit="saveNeedV100(event,'${mode}')" class="rounded-3xl bg-white border border-slate-100 p-5"><h4 class="font-extrabold text-lutmin-dark">Registrar necesidad</h4><input name="title" required class="mt-3 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-sm" placeholder="Ej: reforzar refrigeración"><select name="user" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs"><option value="">Equipo / general</option>${(d.members||[]).map(m=>`<option value="${m.user_id}">${v100Esc(m.full_name)}</option>`).join('')}</select><div class="mt-2 grid grid-cols-2 gap-2"><select name="reason" class="px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs"><option value="brecha">Brecha</option><option value="legal">Requisito legal</option><option value="desempeno">Desempeño</option><option value="promocion">Promoción</option><option value="incorporacion">Incorporación</option><option value="recertificacion">Recertificación</option><option value="otro">Otro</option></select><select name="priority" class="px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs"><option value="media">Media</option><option value="alta">Alta</option><option value="critica">Crítica</option><option value="baja">Baja</option></select></div><input name="due" type="date" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs"><textarea name="notes" rows="3" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Contexto / evidencia"></textarea><button class="mt-3 w-full py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Guardar necesidad</button></form><div class="rounded-3xl bg-white border border-slate-100 overflow-hidden"><div class="p-5 border-b border-slate-100"><h4 class="font-extrabold text-lutmin-dark">Mapa de necesidades</h4></div><div class="divide-y divide-slate-100">${(d.needs||[]).length?(d.needs||[]).map(n=>{const pr=v100Priority(n.priority);return `<div class="p-4"><div class="flex justify-between gap-3"><div><span class="px-2 py-1 rounded-lg text-[9px] font-bold ${pr[1]}">${pr[0]}</span><p class="mt-2 text-sm font-extrabold text-lutmin-dark">${v100Esc(n.title)}</p><p class="mt-1 text-xs text-slate-500">${n.user_id?v100Esc(memberNameV100(d,n.user_id))+' · ':''}${v100Esc(n.reason)} · ${v100Esc(n.status)}${n.due_date?' · '+v100Date(n.due_date):''}</p></div></div></div>`}).join(''):'<div class="p-8 text-sm text-slate-500">Sin necesidades registradas.</div>'}</div></div></div>`;}
async function saveNeedV100(e,mode){e.preventDefault();const f=new FormData(e.target);const {error}=await supabaseClient.rpc('save_training_need_v100',{p_company_id:devCompanyArgV100(mode),p_id:null,p_user_id:f.get('user')||null,p_role_profile_id:null,p_competency_id:null,p_course_id:null,p_title:f.get('title'),p_reason:f.get('reason'),p_priority:f.get('priority'),p_due_date:f.get('due')||null,p_notes:f.get('notes')||null,p_status:'open'});if(error)return showToast(error.message||'No pude guardar la necesidad.');e.target.reset();showToast('Necesidad registrada.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
function renderDevPlanV100(mode,root,d){const plans=d.plans||[],items=d.plan_items||[];root.innerHTML=`<div class="grid xl:grid-cols-[.7fr_1.3fr] gap-4"><form onsubmit="saveAnnualPlanV100(event,'${mode}')" class="rounded-3xl bg-white border border-slate-100 p-5"><h4 class="font-extrabold text-lutmin-dark">Nuevo plan anual</h4><div class="mt-3 grid grid-cols-[100px_1fr] gap-2"><input name="year" type="number" min="2020" max="2100" value="${new Date().getFullYear()}" class="px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs"><input name="name" required class="px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Plan anual de capacitación"></div><textarea name="objective" rows="3" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Objetivo"></textarea><input name="owner" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Responsable"><input name="budget" type="number" min="0" value="0" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Presupuesto interno opcional"><button class="mt-3 w-full py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Crear plan</button></form><div class="space-y-4">${plans.length?plans.map(p=>{const pi=items.filter(x=>x.plan_id===p.id),done=pi.filter(x=>x.status==='completed').length,pct=pi.length?Math.round(done*100/pi.length):0;return `<div class="rounded-3xl bg-white border border-slate-100 p-5"><div class="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-3"><div><p class="text-[10px] uppercase font-bold text-blue-600">${p.plan_year} · ${v100Esc(p.status)}</p><h4 class="mt-1 text-lg font-black text-lutmin-dark">${v100Esc(p.name)}</h4><p class="mt-1 text-xs text-slate-500">${v100Esc(p.objective||'')}</p></div><div class="text-right"><p class="text-2xl font-black text-blue-600">${pct}%</p><p class="text-[10px] text-slate-400">${done}/${pi.length} hitos</p></div></div><div class="mt-4 h-2 rounded-full bg-slate-100 overflow-hidden"><div class="h-full bg-blue-500" style="width:${pct}%"></div></div><form onsubmit="savePlanItemV100(event,'${mode}','${p.id}')" class="mt-4 grid sm:grid-cols-2 xl:grid-cols-5 gap-2"><input name="title" required class="xl:col-span-2 px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Hito / capacitación"><select name="course" class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs"><option value="">Sin curso</option>${(d.courses||[]).map(c=>`<option value="${c.id}">${v100Esc(c.title)}</option>`).join('')}</select><input name="deadline" type="date" class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs"><select name="priority" class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs"><option value="media">Media</option><option value="alta">Alta</option><option value="critica">Crítica</option><option value="baja">Baja</option></select><button class="sm:col-span-2 xl:col-span-5 py-2 rounded-xl bg-blue-600 text-white text-[10px] font-bold">Agregar hito</button></form><div class="mt-3 space-y-2">${pi.map(i=>`<div class="rounded-xl bg-slate-50 p-3 flex justify-between gap-3"><div><p class="text-xs font-bold text-lutmin-dark">${v100Esc(i.title)}</p><p class="text-[10px] text-slate-500">${v100Esc(i.status)}${i.deadline?' · '+v100Date(i.deadline):''}${i.mandatory?' · obligatorio':''}</p></div><span class="text-[10px] font-bold text-slate-400">${i.planned_cost? v100Money(i.planned_cost):''}</span></div>`).join('')||'<p class="text-xs text-slate-400">Sin hitos todavía.</p>'}</div></div>`}).join(''):'<div class="rounded-3xl bg-white border border-slate-100 p-8 text-center text-sm text-slate-500">Todavía no hay plan anual.</div>'}</div></div>`;}
async function saveAnnualPlanV100(e,mode){e.preventDefault();const f=new FormData(e.target);const {error}=await supabaseClient.rpc('save_annual_plan_v100',{p_company_id:devCompanyArgV100(mode),p_id:null,p_year:Number(f.get('year')),p_name:f.get('name'),p_objective:f.get('objective')||null,p_owner_name:f.get('owner')||null,p_status:'active',p_budget:Number(f.get('budget')||0)});if(error)return showToast(error.message||'No pude crear el plan.');e.target.reset();showToast('Plan anual creado.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
async function savePlanItemV100(e,mode,plan){e.preventDefault();const f=new FormData(e.target);const {error}=await supabaseClient.rpc('save_annual_plan_item_v100',{p_company_id:devCompanyArgV100(mode),p_id:null,p_plan_id:plan,p_title:f.get('title'),p_course_id:f.get('course')||null,p_competency_id:null,p_role_profile_id:null,p_target_month:null,p_deadline:f.get('deadline')||null,p_priority:f.get('priority'),p_mandatory:false,p_target_people:0,p_planned_cost:0,p_notes:null,p_status:'planned'});if(error)return showToast(error.message||'No pude agregar el hito.');e.target.reset();showToast('Hito agregado y automatización programada.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
function renderDevIndividualV100(mode,root,d){const plans=d.development_plans||[],items=d.development_items||[];root.innerHTML=`<div class="grid xl:grid-cols-[.75fr_1.25fr] gap-4"><form onsubmit="saveIndividualPlanV100(event,'${mode}')" class="rounded-3xl bg-white border border-slate-100 p-5"><h4 class="font-extrabold text-lutmin-dark">Nuevo plan individual</h4><select name="user" required class="mt-3 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs"><option value="">Elegí persona</option>${(d.members||[]).map(m=>`<option value="${m.user_id}">${v100Esc(m.full_name)}</option>`).join('')}</select><select name="role" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs"><option value="">Sin puesto objetivo</option>${(d.role_profiles||[]).map(r=>`<option value="${r.id}">${v100Esc(r.name)}</option>`).join('')}</select><textarea name="objective" required rows="3" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Objetivo de desarrollo"></textarea><input name="date" type="date" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-xs"><button class="mt-3 w-full py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Crear plan individual</button></form><div class="space-y-3">${plans.length?plans.map(p=>{const pi=items.filter(x=>x.development_plan_id===p.id);return `<div class="rounded-3xl bg-white border border-slate-100 p-5"><p class="text-[10px] uppercase font-bold text-blue-600">${v100Esc(memberNameV100(d,p.user_id))} · ${v100Esc(p.status)}</p><h4 class="mt-1 font-black text-lutmin-dark">${v100Esc(p.objective)}</h4><p class="mt-1 text-xs text-slate-500">Objetivo: ${p.target_date?v100Date(p.target_date):'sin fecha'}</p><form onsubmit="saveIndividualItemV100(event,'${mode}','${p.id}')" class="mt-4 grid sm:grid-cols-2 xl:grid-cols-4 gap-2"><input name="title" required class="xl:col-span-2 px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs" placeholder="Acción de desarrollo"><select name="course" class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs"><option value="">Sin curso</option>${(d.courses||[]).map(c=>`<option value="${c.id}">${v100Esc(c.title)}</option>`).join('')}</select><input name="due" type="date" class="px-3 py-2 rounded-xl bg-slate-50 border border-slate-200 text-xs"><button class="sm:col-span-2 xl:col-span-4 py-2 rounded-xl bg-violet-600 text-white text-[10px] font-bold">Agregar acción</button></form><div class="mt-3 space-y-2">${pi.map(i=>`<div class="rounded-xl bg-slate-50 p-3"><p class="text-xs font-bold">${v100Esc(i.title)}</p><p class="text-[10px] text-slate-500">${v100Esc(i.status)}${i.due_date?' · '+v100Date(i.due_date):''}</p></div>`).join('')||'<p class="text-xs text-slate-400">Sin acciones.</p>'}</div></div>`}).join(''):'<div class="rounded-3xl bg-white border border-slate-100 p-8 text-sm text-slate-500">Todavía no hay planes individuales.</div>'}</div></div>`;}
async function saveIndividualPlanV100(e,mode){e.preventDefault();const f=new FormData(e.target);const {error}=await supabaseClient.rpc('save_development_plan_v100',{p_company_id:devCompanyArgV100(mode),p_id:null,p_user_id:f.get('user'),p_role_profile_id:f.get('role')||null,p_objective:f.get('objective'),p_target_date:f.get('date')||null,p_status:'active'});if(error)return showToast(error.message||'No pude crear el plan individual.');e.target.reset();showToast('Plan individual creado.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
async function saveIndividualItemV100(e,mode,plan){e.preventDefault();const f=new FormData(e.target);const {error}=await supabaseClient.rpc('save_development_item_v100',{p_company_id:devCompanyArgV100(mode),p_id:null,p_plan_id:plan,p_title:f.get('title'),p_competency_id:null,p_course_id:f.get('course')||null,p_target_level:null,p_due_date:f.get('due')||null,p_status:'pending',p_notes:null});if(error)return showToast(error.message||'No pude agregar la acción.');e.target.reset();showToast('Acción individual agregada.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}
function renderDevAutomationV100(mode,root,d){const globals=new Map(),rows=d.rules||[];rows.filter(x=>!x.company_id).forEach(x=>globals.set(x.code,x));const effective=[...globals.values()].map(g=>rows.find(x=>x.company_id&&x.code===g.code)||g);root.innerHTML=`<div class="grid lg:grid-cols-2 gap-4">${effective.map(r=>`<div class="rounded-3xl bg-white border border-slate-100 p-5 flex items-start justify-between gap-4"><div><div class="w-10 h-10 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center"><i class="fa-solid fa-bolt"></i></div><h4 class="mt-3 font-extrabold text-lutmin-dark">${v100Esc(r.name)}</h4><p class="mt-1 text-xs text-slate-500">${v100Esc(r.description||'')}</p><p class="mt-2 text-[10px] text-slate-400">Interna · sin API externa · ${v100Esc(r.config?.mode||'regla')}</p></div><button onclick="toggleDevRuleV100('${mode}','${v100Esc(r.code)}',${r.active?'false':'true'})" class="px-3 py-2 rounded-xl ${r.active?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'} text-xs font-bold">${r.active?'Activa':'Pausada'}</button></div>`).join('')}</div><div class="mt-4 rounded-3xl bg-amber-50 border border-amber-100 p-5"><p class="font-extrabold text-amber-900">Límite consciente de la versión sin costo</p><p class="mt-2 text-xs text-amber-800">Estas automatizaciones reaccionan a cambios de datos mediante triggers y acciones programadas. No usan WhatsApp, SMS, un LLM ni un servicio de cron pago. Si en el futuro conectamos un agente generativo externo, quedará como capa opcional.</p></div>`;}
async function toggleDevRuleV100(mode,code,active){const {error}=await supabaseClient.rpc('set_automation_rule_v100',{p_company_id:devCompanyArgV100(mode),p_code:code,p_active:active});if(error)return showToast(error.message||'No pude cambiar la regla.');showToast(active?'Automatización activada.':'Automatización pausada.');mode==='admin'?await loadAdminDevelopmentV100():await loadCompanyDevelopmentV100();}

// -------------------------------------------------------------
// C) COMERCIAL V10 · descuento + checkout manual sin gateway
// -------------------------------------------------------------
function ensureAdminCommercialV100(){const admin=document.querySelector('section[data-campus-panel="admin"]');if(!admin||document.getElementById('adminCommercialV100'))return;const w=document.createElement('div');w.id='adminCommercialV100';w.dataset.adminModuleV19='commercial';w.className='mt-6 rounded-3xl bg-white border border-slate-100 p-5 sm:p-6';w.innerHTML=`<div class="flex justify-between gap-4"><div><p class="text-[10px] uppercase font-black tracking-widest text-lutmin-light">Comercial autogestionado</p><h3 class="mt-1 text-xl font-black text-lutmin-dark">Reservas y descuentos sin pasarela paga</h3><p class="mt-1 text-xs text-slate-500">El alumno reserva, aplica código y puede informar referencia de transferencia. Administración confirma y recién ahí se crea la matrícula.</p></div><button onclick="loadCommercialV100()" class="h-fit px-3 py-2 rounded-xl bg-slate-100 text-xs font-bold">Actualizar</button></div><div class="mt-5 grid xl:grid-cols-[.7fr_1.3fr] gap-4"><form onsubmit="saveDiscountV100(event)" class="rounded-2xl bg-slate-50 p-4"><h4 class="font-extrabold text-sm text-lutmin-dark">Nuevo código de descuento</h4><input name="code" required class="mt-3 w-full px-3 py-2.5 rounded-xl bg-white border border-slate-200 text-xs uppercase" placeholder="EJ: LUTMIN10"><div class="mt-2 grid grid-cols-2 gap-2"><select name="type" class="px-3 py-2.5 rounded-xl bg-white border border-slate-200 text-xs"><option value="percent">Porcentaje</option><option value="fixed">Importe fijo</option></select><input name="value" required type="number" min="1" step="0.01" class="px-3 py-2.5 rounded-xl bg-white border border-slate-200 text-xs" placeholder="10"></div><select id="discountOfferingV100" name="offering" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-white border border-slate-200 text-xs"><option value="">Todas las ediciones</option></select><input name="max" type="number" min="1" class="mt-2 w-full px-3 py-2.5 rounded-xl bg-white border border-slate-200 text-xs" placeholder="Usos máximos (opcional)"><button class="mt-3 w-full py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-bold">Crear código</button></form><div><div id="checkoutListV100" class="space-y-2"></div><div id="discountListV100" class="mt-4 flex flex-wrap gap-2"></div></div></div>`;admin.appendChild(w);}
async function loadCommercialV100(){if(currentLutminUser?.role!=='admin')return;ensureAdminCommercialV100();const offerSel=document.getElementById('discountOfferingV100');if(offerSel){const val=offerSel.value;offerSel.innerHTML='<option value="">Todas las ediciones</option>'+(adminOfferings||[]).map(o=>{const c=adminCourses.find(x=>x.id===o.course_id);return `<option value="${o.id}">${v100Esc(c?.title||'Curso')} · ${v100Date(o.start_date)}</option>`}).join('');offerSel.value=val;}const {data,error}=await supabaseClient.rpc('admin_commercial_center_v100');if(error){console.error(error);document.getElementById('checkoutListV100').innerHTML='<div class="rounded-xl bg-amber-50 p-3 text-xs text-amber-800">Este módulo todavía no está habilitado. Contactá a Administración.</div>';return;}commercialV100=data||{discounts:[],checkouts:[]};renderCommercialV100();}
function renderCommercialV100(){const check=document.getElementById('checkoutListV100'),discount=document.getElementById('discountListV100');if(check)check.innerHTML=(commercialV100.checkouts||[]).length?(commercialV100.checkouts||[]).slice(0,30).map(r=>`<div class="rounded-2xl border border-slate-100 p-4 flex flex-col lg:flex-row lg:items-center lg:justify-between gap-3"><div><div class="flex gap-2"><span class="px-2 py-1 rounded-lg bg-blue-50 text-blue-700 text-[9px] font-bold">${v100Esc(r.status)}</span>${Number(r.discount_amount||0)>0?'<span class="px-2 py-1 rounded-lg bg-violet-50 text-violet-700 text-[9px] font-bold">DESCUENTO</span>':''}</div><p class="mt-2 text-sm font-extrabold text-lutmin-dark">${v100Esc(r.full_name||r.email)} · ${v100Esc(r.course_title)}</p><p class="mt-1 text-xs text-slate-500">${v100Date(r.start_date)} · ${v100Money(r.final_price,r.currency)}${r.payment_reference?' · Ref. '+v100Esc(r.payment_reference):' · sin referencia de pago'}</p></div><div class="flex gap-2">${!['confirmed','rejected'].includes(r.status)?`<button onclick="confirmCheckoutV100('${r.id}')" class="px-3 py-2 rounded-xl bg-emerald-50 text-emerald-700 text-xs font-bold">Confirmar y matricular</button><button onclick="rejectCheckoutV100('${r.id}')" class="px-3 py-2 rounded-xl bg-red-50 text-red-700 text-xs font-bold">Rechazar</button>`:''}</div></div>`).join(''):'<div class="rounded-2xl bg-slate-50 p-5 text-sm text-slate-500">No hay reservas autogestionadas.</div>';if(discount)discount.innerHTML=(commercialV100.discounts||[]).map(d=>`<span class="px-3 py-2 rounded-xl ${d.active?'bg-violet-50 text-violet-700':'bg-slate-100 text-slate-400'} text-xs font-bold">${v100Esc(d.code)} · ${d.discount_type==='percent'?Number(d.discount_value)+'%':v100Money(d.discount_value)} · ${d.uses_count||0}${d.max_uses?'/'+d.max_uses:''} usos</span>`).join('')||'<span class="text-xs text-slate-400">Sin códigos.</span>';}
async function saveDiscountV100(e){e.preventDefault();const f=new FormData(e.target);const {error}=await supabaseClient.rpc('admin_save_discount_v100',{p_id:null,p_code:f.get('code'),p_course_id:null,p_offering_id:f.get('offering')||null,p_type:f.get('type'),p_value:Number(f.get('value')),p_starts_at:null,p_ends_at:null,p_max_uses:f.get('max')?Number(f.get('max')):null,p_active:true});if(error)return showToast(error.message||'No pude crear el código.');e.target.reset();showToast('Código creado.');await loadCommercialV100();}
async function confirmCheckoutV100(id){if(!confirm('¿Confirmar el pago/reserva y crear la matrícula con acceso al curso?'))return;const {error}=await supabaseClient.rpc('admin_confirm_checkout_v100',{p_request_id:id});if(error)return showToast(error.message||'No pude confirmar.');showToast('Reserva confirmada y matrícula creada.');await loadAdminData();await loadCommercialV100();}
async function rejectCheckoutV100(id){const {error}=await supabaseClient.rpc('admin_reject_checkout_v100',{p_request_id:id});if(error)return showToast(error.message||'No pude rechazar.');showToast('Reserva rechazada.');await loadCommercialV100();}

const _openPublicCourseV100=typeof openPublicCourse==='function'?openPublicCourse:null;
if(_openPublicCourseV100)openPublicCourse=function(courseId){const r=_openPublicCourseV100.apply(this,arguments);setTimeout(()=>enhanceCourseCheckoutV100(courseId),0);return r;};
function enhanceCourseCheckoutV100(courseId){const course=(publicCatalog||[]).find(c=>c.id===courseId),root=document.getElementById('publicCourseOfferings');if(!course||!root)return;const cards=[...root.querySelectorAll('.rounded-2xl.border.border-blue-100')];cards.forEach((card,i)=>{const o=course.offerings?.[i];if(!o||card.querySelector('[data-v100-checkout]'))return;const actions=card.lastElementChild?.tagName==='BUTTON'?card:card;const btn=document.createElement('button');btn.dataset.v100Checkout='1';btn.className='px-4 py-2.5 rounded-xl bg-lutmin-dark text-white text-xs font-extrabold sm:ml-2';btn.textContent='Reservar / inscribirme';btn.onclick=()=>openCheckoutV100(o.id);const existing=card.querySelector('button:last-child');existing?.insertAdjacentElement('afterend',btn);});}
async function openCheckoutV100(offeringId){if(!supabaseClient)return;const {data:{session}}=await supabaseClient.auth.getSession();if(!session){openAuthModal('campus');document.getElementById('authStatus').textContent='Ingresá con tu cuenta de alumno para reservar esta edición.';return;}await loadCurrentLutminUser(session.user);if(currentLutminUser?.role!=='student')return showToast('La inscripción autogestionada está disponible para cuentas de alumno.');const m=ensureV100Modal('checkoutModalV100','max-w-xl'),b=m.querySelector('[data-v100-body]');b.innerHTML=`<p class="text-[10px] uppercase tracking-widest font-black text-lutmin-light">Inscripción autogestionada · sin pasarela</p><h2 class="mt-2 text-2xl font-black text-lutmin-dark">Reservar edición</h2><div id="checkoutQuoteV100" class="mt-4 rounded-2xl bg-slate-50 p-4 text-sm text-slate-500">Calculando...</div><form onsubmit="submitCheckoutV100(event,'${offeringId}')" class="mt-4 space-y-3"><div><label class="text-xs font-bold text-slate-600">Código de descuento (opcional)</label><div class="mt-1 flex gap-2"><input id="checkoutCodeV100" class="flex-1 px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-sm uppercase"><button type="button" onclick="quoteCheckoutV100('${offeringId}')" class="px-3 py-2 rounded-xl bg-blue-50 text-blue-700 text-xs font-bold">Aplicar</button></div></div><div><label class="text-xs font-bold text-slate-600">Referencia de transferencia (opcional)</label><input id="checkoutReferenceV100" class="mt-1 w-full px-3 py-2.5 rounded-xl bg-slate-50 border border-slate-200 text-sm" placeholder="Podés reservar ahora y completar esto después con Administración"></div><div class="rounded-xl bg-amber-50 border border-amber-100 p-3 text-[11px] text-amber-800">Esto no cobra automáticamente. La matrícula y el acceso se habilitan cuando Administración confirma la reserva/pago.</div><button class="w-full py-3 rounded-xl bg-lutmin-dark text-white font-extrabold">Enviar reserva</button></form>`;showV100Modal('checkoutModalV100');await quoteCheckoutV100(offeringId);}
async function quoteCheckoutV100(offeringId){const code=document.getElementById('checkoutCodeV100')?.value.trim()||null,root=document.getElementById('checkoutQuoteV100');const {data,error}=await supabaseClient.rpc('student_checkout_quote_v100',{p_offering_id:offeringId,p_code:code});if(error){if(root)root.innerHTML=`<span class="text-red-600">${v100Esc(error.message)}</span>`;return null;}if(root)root.innerHTML=`<div class="flex justify-between"><span>Precio</span><strong>${v100Money(data.list_price,data.currency)}</strong></div>${Number(data.discount_amount||0)>0?`<div class="mt-1 flex justify-between text-violet-700"><span>Descuento</span><strong>-${v100Money(data.discount_amount,data.currency)}</strong></div>`:''}<div class="mt-2 pt-2 border-t border-slate-200 flex justify-between text-lutmin-dark"><span class="font-bold">Total</span><strong class="text-lg">${v100Money(data.final_price,data.currency)}</strong></div>${data.available_seats!==null?`<p class="mt-2 text-[10px] text-slate-400">${data.available_seats} cupos disponibles</p>`:''}`;return data;}
async function submitCheckoutV100(e,offeringId){e.preventDefault();const code=document.getElementById('checkoutCodeV100')?.value.trim()||null,ref=document.getElementById('checkoutReferenceV100')?.value.trim()||null;const {data,error}=await supabaseClient.rpc('student_create_checkout_v100',{p_offering_id:offeringId,p_code:code,p_payment_reference:ref});if(error)return showToast(error.message||'No pude registrar la reserva.');hideV100Modal('checkoutModalV100');showToast(data?.status==='submitted'?'Reserva enviada a Administración.':'Reserva creada. Administración te indicará cómo completar el pago.');}

// -------------------------------------------------------------
// D) Integración con cargas existentes
// -------------------------------------------------------------
const _loadTalentCenterV100=typeof loadTalentCenter==='function'?loadTalentCenter:null;
if(_loadTalentCenterV100)loadTalentCenter=async function(){const r=await _loadTalentCenterV100.apply(this,arguments);await loadTalentSnapshotsV100();ensureTalentAgentV100();refreshTalentAgentOptionsV100();enhanceTalentApplicationsV100();return r;};
const _loadCompanyPortalDataV100=typeof loadCompanyPortalData==='function'?loadCompanyPortalData:null;
if(_loadCompanyPortalDataV100)loadCompanyPortalData=async function(){const r=await _loadCompanyPortalDataV100.apply(this,arguments);ensureCompanyDevelopmentPanelV100();await loadCompanyDevelopmentV100();return r;};
const _loadAdminDataV100=typeof loadAdminData==='function'?loadAdminData:null;
if(_loadAdminDataV100)loadAdminData=async function(){const r=await _loadAdminDataV100.apply(this,arguments);if(currentLutminUser?.role==='admin'){ensureAdminDevelopmentNavV100();ensureAdminDevelopmentPanelV100();ensureAdminCommercialV100();await Promise.allSettled([loadAdminDevelopmentV100(),loadCommercialV100()]);}return r;};

function initV100(){
  document.title='Lutmin | Plataforma V10.0';
  if(currentLutminUser?.role==='student'){ensureTalentAgentV100();refreshTalentAgentOptionsV100();}
  if(currentLutminUser?.role==='company_admin')ensureCompanyDevelopmentPanelV100();
  if(currentLutminUser?.role==='admin'){ensureAdminDevelopmentNavV100();ensureAdminDevelopmentPanelV100();ensureAdminCommercialV100();}
}
document.addEventListener('DOMContentLoaded',()=>setTimeout(initV100,1250),{once:true});

